package com.taskforge.worker;
import com.taskforge.job.*;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.kafka.support.Acknowledgment;import org.springframework.stereotype.Component;import java.time.Duration;import java.util.UUID;
@Component @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="taskforge.role",havingValue="worker") public class ExecutionConsumer {
 private final StringRedisTemplate redis;private final JobRepository jobs;private final JobExecutionRepository executions;private final DemoHandlers handlers;private final org.springframework.kafka.core.KafkaTemplate<String,JobMessage> kafka;
 public ExecutionConsumer(StringRedisTemplate r,JobRepository j,JobExecutionRepository e,DemoHandlers h,org.springframework.kafka.core.KafkaTemplate<String,JobMessage> k){redis=r;jobs=j;executions=e;handlers=h;kafka=k;}
 @KafkaListener(topics="taskforge.jobs.execute",groupId="taskforge-workers") public void receive(JobMessage m,Acknowledgment ack){String key="taskforge:lock:job:"+m.jobId(),token=UUID.randomUUID().toString();Boolean acquired=redis.opsForValue().setIfAbsent(key,token,Duration.ofSeconds(Math.max(30,m.timeoutSeconds()+15L)));if(!Boolean.TRUE.equals(acquired)){ack.acknowledge();return;}try{JobExecution e=executions.findById(m.executionId()).orElse(null);if(e==null||e.getStatus()!=JobStatus.QUEUED){ack.acknowledge();return;}Job j=jobs.findById(m.jobId()).orElseThrow();if(j.getStatus()!=JobStatus.QUEUED){ack.acknowledge();return;}e.start(System.getenv().getOrDefault("HOSTNAME","worker"));j.transition(JobStatus.RUNNING);jobs.save(j);executions.save(e);try{handlers.get(m.type()).execute(m);e.finish(JobStatus.SUCCESS,null);j.transition(JobStatus.SUCCESS);}catch(Exception ex){boolean retry=m.attempt()<=j.getMaxRetries();e.finish(JobStatus.FAILED,ex.getMessage());if(retry){j.transition(JobStatus.RETRYING);j.setNextRunAt(java.time.Instant.now().plusSeconds(Math.min(300,1L<<Math.min(8,m.attempt()))));}else j.transition(JobStatus.FAILED);}jobs.save(j);executions.save(e);ack.acknowledge();}finally{String script="if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end";redis.execute(new org.springframework.data.redis.core.script.DefaultRedisScript<>(script,Long.class),java.util.List.of(key),token);}}
}
